-- =====================================================================
-- GeoSmart Civil: datos de ejemplo (3 empresas, 3 obras, vuelos, alertas...)
-- Ejecuta este archivo DESPUÉS de 1-esquema.sql, en el SQL Editor de Supabase.
-- Códigos para unirse a cada empresa de ejemplo al crear una cuenta:
--   DEMOVLA1  -> Carretera Vía Los Andes
--   DEMOLPR2  -> Habilitación urbana Las Praderas
--   DEMOLCE3  -> Edificio Los Cedros
-- =====================================================================
on conflict (id) do nothing;

on conflict (coleccion, id) do update set data = excluded.data, empresa_id = excluded.empresa_id;
